import * as THREE from 'three'
import { useEffect, useMemo, useRef, useState } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'

/**
 * Aagami SEQ — nanopore sequencing scroll hero.
 * A DNA double helix threads vertically through a flat membrane nanopore.
 * Scroll drives the helix upward through the pore, then the brand reveals.
 */

// ── scratch vectors (reused, never leaked between frames) ──────────────────
const cameraTarget = new THREE.Vector3()
const lookAtTarget = new THREE.Vector3()
const poreScale = new THREE.Vector3(1, 1, 1)
const _up = new THREE.Vector3(0, 1, 0)
const _dir = new THREE.Vector3()
const _quat = new THREE.Quaternion()
const _fogA = new THREE.Color('#061820')
const _fogB = new THREE.Color('#0a2438')
const _fogC = new THREE.Color('#0c2a28')
const _fogNow = new THREE.Color()

// ── palette ────────────────────────────────────────────────────────────────
const C = {
  steel: '#6a7f88',
  slate: '#4a5c66',
  bone: '#c5cfc8',
  teal: '#3d7a74',
  deepTeal: '#2a5552',
  ice: '#8aa4ae',
  mutedBlue: '#4a6a82',
  graphite: '#3a4248',
  moss: '#5a6b4a',
  copper: '#8a6a55',
  ghost: '#9bb0b4',
  // DNA base colours (muted, clinical)
  adenine: '#c0504a',   // red-ish
  thymine: '#e8e0d0',   // off-white
  guanine: '#4a82b8',   // blue
  cytosine: '#5a9a8a',  // teal
}
const BOND_DARK = '#3e4a50'
const BOND_MID = '#5a6870'

// ── helpers ────────────────────────────────────────────────────────────────
const clamp = (v, min = 0, max = 1) => Math.min(Math.max(v, min), max)
const smooth = (a, b, v) => {
  const n = clamp((v - a) / (b - a))
  return n * n * (3 - 2 * n)
}
const lerp = THREE.MathUtils.lerp

function seededRandom(seed) {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453
  return x - Math.floor(x)
}

function bondQuat(dir) {
  _dir.set(dir[0], dir[1], dir[2]).normalize()
  return _quat.setFromUnitVectors(_up, _dir).clone()
}

// ── scroll timeline ────────────────────────────────────────────────────────
// 0%   5%──20%    20%──35%   35%──72%   65%──80%   78%──92%
// idle  focus       poreIn   threading   poreOut    brand
const BEATS = {
  focusStart: 0.05,
  focusEnd: 0.22,
  poreInStart: 0.20,
  poreInEnd: 0.35,
  transitStart: 0.35,
  transitEnd: 0.72,
  clearStart: 0.55,
  clearEnd: 0.75,
  poreOutStart: 0.65,
  poreOutEnd: 0.80,
  brandStart: 0.78,
  brandEnd: 0.92,
}

const progressApi = { current: 0, target: 0 }

// ── field molecule blueprints (background) ─────────────────────────────────
const STRUCTURES = [
  { kind: 'mono', core: C.steel, coreR: 0.34, tips: [] },
  { kind: 'di', core: C.slate, coreR: 0.22, tips: [{ pos: [0.55, 0.05, 0], color: C.ice, r: 0.2 }] },
  {
    kind: 'tri',
    core: C.teal,
    coreR: 0.2,
    tips: [
      { pos: [0.48, 0.28, 0.1], color: C.bone, r: 0.16 },
      { pos: [-0.42, 0.22, -0.12], color: C.mutedBlue, r: 0.15 },
    ],
  },
  {
    kind: 'tetra',
    core: C.deepTeal,
    coreR: 0.18,
    tips: [
      { pos: [0.42, 0.35, 0.15], color: C.moss, r: 0.14 },
      { pos: [-0.4, 0.28, 0.2], color: C.ice, r: 0.13 },
      { pos: [0.05, -0.42, 0.22], color: C.copper, r: 0.15 },
      { pos: [0.1, 0.08, -0.48], color: C.steel, r: 0.14 },
    ],
  },
  {
    kind: 'ring',
    core: C.ghost,
    coreR: 0.12,
    tips: [
      { pos: [0.45, 0, 0], color: C.ice, r: 0.11 },
      { pos: [0.22, 0, 0.39], color: C.ghost, r: 0.11 },
      { pos: [-0.22, 0, 0.39], color: C.steel, r: 0.11 },
      { pos: [-0.45, 0, 0], color: C.ghost, r: 0.11 },
      { pos: [-0.22, 0, -0.39], color: C.ice, r: 0.11 },
      { pos: [0.22, 0, -0.39], color: C.slate, r: 0.11 },
    ],
  },
]

const MAT_PRESETS = [
  { metalness: 0.55, roughness: 0.35, opacity: 1, emissiveIntensity: 0.08 },
  { metalness: 0.15, roughness: 0.55, opacity: 1, emissiveIntensity: 0.05 },
  { metalness: 0.3, roughness: 0.2, opacity: 0.55, emissiveIntensity: 0.12 },
  { metalness: 0.7, roughness: 0.18, opacity: 0.92, emissiveIntensity: 0.15 },
  { metalness: 0.05, roughness: 0.7, opacity: 0.4, emissiveIntensity: 0.2 },
]

// DNA base colour sequence (A T G C repeating)
const BASE_COLORS = [C.adenine, C.thymine, C.guanine, C.cytosine]

// ── App ────────────────────────────────────────────────────────────────────
export default function App() {
  const [ui, setUi] = useState({ brand: 0, hint: 1 })

  useEffect(() => {
    const onScroll = () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight
      progressApi.target = scrollable > 0 ? clamp(window.scrollY / scrollable) : 0
    }
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', onScroll)

    let raf = 0
    let lastKey = -1
    const tick = () => {
      progressApi.current = lerp(progressApi.current, progressApi.target, 0.085)
      const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progressApi.current)
      const hint = 1 - smooth(0.02, 0.1, progressApi.current)
      const key = Math.round(brand * 50) + Math.round(hint * 50) * 100
      if (key !== lastKey) {
        lastKey = key
        setUi({ brand, hint })
      }
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => {
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onScroll)
      cancelAnimationFrame(raf)
    }
  }, [])

  return (
    <main className="experience-shell">
      <div className="gradient-wash" aria-hidden />
      <div className="grain-overlay" aria-hidden />

      <div className="canvas-stage">
        <Canvas
          dpr={[1, 1.5]}
          camera={{ position: [0, 0, 12], fov: 36, near: 0.1, far: 90 }}
          gl={{ antialias: true, alpha: true, powerPreference: 'high-performance' }}
          onCreated={({ gl }) => {
            gl.setClearColor(0x000000, 0)
            gl.toneMapping = THREE.ACESFilmicToneMapping
            gl.toneMappingExposure = 0.92
          }}>
          <Atmosphere />
          <ambientLight intensity={0.4} color="#8a9aa0" />
          <directionalLight position={[6, 10, 4]} intensity={1.4} color="#e8eee8" />
          <directionalLight position={[-5, 2, -4]} intensity={0.5} color="#4a6a78" />
          <pointLight position={[0, 0, 6]} intensity={0.6} color="#6a9088" distance={30} />

          <CameraRig />
          <Starfield />
          <FieldMolecules />
          <DNAHelix />
          <Nanopore />
        </Canvas>

        <div className="scroll-hint" style={{ opacity: ui.hint }}>
          Scroll to sequence
        </div>

        <div className="brand-reveal" style={{ opacity: ui.brand }}>
          <div className="brand-name">
            AAGAMI
            <span>
              SE
              <span className="brand-q">
                Q
                <i className="brand-q-dot" aria-hidden />
              </span>
            </span>
          </div>
          <p className="brand-tagline">Clarity in the fight against cancer</p>
        </div>
      </div>
      <div className="scroll-space" aria-hidden />
    </main>
  )
}

// ── Atmosphere ─────────────────────────────────────────────────────────────
function Atmosphere() {
  const fogRef = useRef()

  useFrame((state) => {
    const t = state.clock.elapsedTime * 0.08
    const w1 = (Math.sin(t) + 1) * 0.5
    const w2 = (Math.sin(t * 0.7 + 1.2) + 1) * 0.5
    _fogNow.copy(_fogA).lerp(_fogB, w1).lerp(_fogC, w2 * 0.45)
    if (fogRef.current) fogRef.current.color.copy(_fogNow)
    document.documentElement.style.setProperty('--fog-r', String(Math.round(_fogNow.r * 255)))
    document.documentElement.style.setProperty('--fog-g', String(Math.round(_fogNow.g * 255)))
    document.documentElement.style.setProperty('--fog-b', String(Math.round(_fogNow.b * 255)))
  })

  return <fog ref={fogRef} attach="fog" args={['#061820', 16, 38]} />
}

// ── CameraRig ──────────────────────────────────────────────────────────────
// Phase 0 (idle):    slightly elevated, looking at helix centre
// Phase 1 (focus):   pull in, tilt to see helix entering pore from side
// Phase 2 (transit): hold side-on view tracking the threading
// Phase 3 (brand):   zoom back out, helix recedes, brand appears
function CameraRig() {
  const { camera } = useThree()

  useFrame((_, delta) => {
    const p = progressApi.current
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, p)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, p)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, p)

    // Camera moves from front-centre → slight right + closer for threading view
    const camX = lerp(0, 1.8, focus) * (1 - brand)
    const camY = lerp(0.5, 0.2, focus) * (1 - brand * 0.6)
    const camZ = lerp(12, 9.5, focus) * lerp(1, 1.08, brand)

    cameraTarget.set(camX, camY, camZ)
    // Look at the pore (y=0) during transit, drift up for brand
    lookAtTarget.set(0, lerp(0.5, 0, focus) * (1 - transit * 0.6) + brand * 0.8, 0)

    camera.position.lerp(cameraTarget, 1 - Math.exp(-delta * 3.2))
    camera.lookAt(lookAtTarget)
    camera.fov = lerp(36, 32, focus)
    camera.updateProjectionMatrix()
  })

  return null
}

// ── AtomMaterial ───────────────────────────────────────────────────────────
function AtomMaterial({ color, preset, emissiveBoost = 0 }) {
  const p = MAT_PRESETS[preset % MAT_PRESETS.length]
  return (
    <meshStandardMaterial
      color={color}
      emissive={color}
      emissiveIntensity={p.emissiveIntensity + emissiveBoost}
      metalness={p.metalness}
      roughness={p.roughness}
      transparent={p.opacity < 0.98}
      opacity={p.opacity}
      depthWrite={p.opacity > 0.7}
    />
  )
}

// ── StructureMesh ──────────────────────────────────────────────────────────
function StructureMesh({ structureIndex, matPreset }) {
  const def = STRUCTURES[structureIndex % STRUCTURES.length]
  const bondColor = matPreset % 2 === 0 ? BOND_DARK : BOND_MID

  return (
    <group>
      <mesh>
        <sphereGeometry args={[def.coreR, 24, 24]} />
        <AtomMaterial color={def.core} preset={matPreset} />
      </mesh>
      {def.tips.map((tip, i) => {
        const mid = [tip.pos[0] * 0.5, tip.pos[1] * 0.5, tip.pos[2] * 0.5]
        const length = Math.hypot(tip.pos[0], tip.pos[1], tip.pos[2]) * 0.68
        const tipPreset = (matPreset + i) % MAT_PRESETS.length
        return (
          <group key={i}>
            <mesh position={mid} quaternion={bondQuat(tip.pos)}>
              <cylinderGeometry args={[0.028, 0.028, length, 6]} />
              <meshStandardMaterial
                color={bondColor}
                metalness={0.4}
                roughness={0.5}
                transparent={MAT_PRESETS[matPreset].opacity < 0.9}
                opacity={Math.min(1, MAT_PRESETS[matPreset].opacity + 0.15)}
              />
            </mesh>
            <mesh position={tip.pos}>
              <sphereGeometry args={[tip.r, 16, 16]} />
              <AtomMaterial color={tip.color} preset={tipPreset} />
            </mesh>
          </group>
        )
      })}
    </group>
  )
}

// ── FieldMolecules ─────────────────────────────────────────────────────────
function FieldMolecules() {
  const group = useRef()
  const layout = useMemo(() => {
    const items = []
    for (let i = 0; i < 40; i += 1) {
      items.push({
        base: [
          (seededRandom(i + 2) - 0.5) * 18,
          (seededRandom(i + 19) - 0.5) * 8,
          (seededRandom(i + 37) - 0.5) * 10 - 2,
        ],
        scale: 0.4 + seededRandom(i + 51) * 0.7,
        drift: 0.2 + seededRandom(i + 67) * 0.5,
        phase: seededRandom(i + 83) * Math.PI * 2,
        structure: Math.floor(seededRandom(i + 99) * STRUCTURES.length),
        matPreset: Math.floor(seededRandom(i + 111) * MAT_PRESETS.length),
      })
    }
    return items
  }, [])

  useFrame((state) => {
    if (!group.current) return
    const p = progressApi.current
    const t = state.clock.elapsedTime
    const clear = smooth(BEATS.clearStart, BEATS.clearEnd, p)
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, p)
    const fade = (1 - focus * 0.25) * (1 - clear)

    group.current.visible = fade > 0.04
    group.current.children.forEach((child, i) => {
      const item = layout[i]
      if (!item) return
      child.position.set(
        item.base[0] + Math.cos(t * item.drift * 0.65 + item.phase) * 0.3,
        item.base[1] + Math.sin(t * item.drift + item.phase) * 0.22,
        item.base[2] + Math.sin(t * item.drift * 0.5 + item.phase) * 0.25,
      )
      child.rotation.x = t * 0.04 * item.drift
      child.rotation.y = t * 0.08 * item.drift + item.phase
      child.scale.setScalar(item.scale * (0.5 + fade * 0.5))
    })
  })

  return (
    <group ref={group}>
      {layout.map((item, i) => (
        <group key={i}>
          <StructureMesh structureIndex={item.structure} matPreset={item.matPreset} />
        </group>
      ))}
    </group>
  )
}

// ── DNAHelix ───────────────────────────────────────────────────────────────
// A double helix with two backbone strands + base-pair rungs.
// The whole group translates upward through Y=0 (the pore plane) as scroll progresses.
//
// Geometry is static — we just move the group's Y position.
// Helix starts below the pore (negative Y) and threads upward through it.
//
// Parameters:
//   HELIX_RADIUS    — radius of each backbone from helix axis
//   HELIX_PITCH     — vertical distance per full turn
//   BASE_PAIRS      — number of base-pair rungs
//   STRAND_SEGMENTS — cylinder segments per backbone section

const HELIX_RADIUS = 0.55
const HELIX_PITCH = 1.8       // one full turn per 1.8 units
const BASE_PAIRS = 32         // rungs
const PAIR_SPACING = 0.42     // vertical gap between base pairs

// Total helix height
const HELIX_HEIGHT = BASE_PAIRS * PAIR_SPACING  // ~13.4 units

function DNAHelix() {
  const group = useRef()
  const helixYRef = useRef(0)

  // Pre-compute helix geometry data
  const { backboneA, backboneB, basePairs } = useMemo(() => {
    const bpA = []
    const bpB = []
    const pairs = []

    for (let i = 0; i < BASE_PAIRS; i++) {
      const t = i / BASE_PAIRS
      const angle = t * Math.PI * 2 * (HELIX_HEIGHT / HELIX_PITCH)
      const y = i * PAIR_SPACING - HELIX_HEIGHT / 2  // centred at 0

      const ax = Math.cos(angle) * HELIX_RADIUS
      const az = Math.sin(angle) * HELIX_RADIUS
      const bx = Math.cos(angle + Math.PI) * HELIX_RADIUS
      const bz = Math.sin(angle + Math.PI) * HELIX_RADIUS

      bpA.push([ax, y, az])
      bpB.push([bx, y, bz])
      pairs.push({
        posA: [ax, y, az],
        posB: [bx, y, bz],
        color: BASE_COLORS[i % 4],
        y,
      })
    }

    return { backboneA: bpA, backboneB: bpB, basePairs: pairs }
  }, [])

  useFrame((_, delta) => {
    if (!group.current) return
    const p = progressApi.current
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, p)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, p)
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, p)

    // Threading: helix moves from below (negative Y) up through pore at Y=0
    // At transit=0: bottom of helix just below pore → helixY = -HELIX_HEIGHT * 0.5
    // At transit=1: top of helix just above pore   → helixY = +HELIX_HEIGHT * 0.5
    const threadY = lerp(-HELIX_HEIGHT * 0.48, HELIX_HEIGHT * 0.48, transit)
    // On brand, drift upward slightly and shrink
    const brandY = brand * 2.5
    const targetY = threadY + brandY

    helixYRef.current = lerp(helixYRef.current, targetY, 1 - Math.exp(-delta * 4))
    group.current.position.y = helixYRef.current

    // Slow idle rotation around Y axis
    group.current.rotation.y += delta * 0.18

    // Scale: grow in as pore appears, shrink away on brand
    const poreIn = smooth(BEATS.poreInStart, BEATS.poreInEnd, p)
    const scale = lerp(0, 1, poreIn) * lerp(1, 0.15, brand)
    group.current.scale.setScalar(scale)
    group.current.visible = scale > 0.01
  })

  return (
    <group ref={group}>
      {/* Backbone A — teal/steel spheres */}
      {backboneA.map((pos, i) => (
        <mesh key={`a${i}`} position={pos}>
          <sphereGeometry args={[0.1, 10, 10]} />
          <meshStandardMaterial
            color={C.teal}
            emissive={C.teal}
            emissiveIntensity={0.2}
            metalness={0.5}
            roughness={0.3}
          />
        </mesh>
      ))}

      {/* Backbone B — ice/steel spheres */}
      {backboneB.map((pos, i) => (
        <mesh key={`b${i}`} position={pos}>
          <sphereGeometry args={[0.1, 10, 10]} />
          <meshStandardMaterial
            color={C.ice}
            emissive={C.ice}
            emissiveIntensity={0.15}
            metalness={0.5}
            roughness={0.3}
          />
        </mesh>
      ))}

      {/* Backbone bonds A — cylinders connecting consecutive A nodes */}
      {backboneA.slice(0, -1).map((pos, i) => {
        const next = backboneA[i + 1]
        const mid = [(pos[0] + next[0]) / 2, (pos[1] + next[1]) / 2, (pos[2] + next[2]) / 2]
        const dx = next[0] - pos[0]
        const dy = next[1] - pos[1]
        const dz = next[2] - pos[2]
        const len = Math.hypot(dx, dy, dz)
        return (
          <mesh key={`ab${i}`} position={mid} quaternion={bondQuat([dx, dy, dz])}>
            <cylinderGeometry args={[0.04, 0.04, len, 6]} />
            <meshStandardMaterial color={C.deepTeal} metalness={0.4} roughness={0.5} />
          </mesh>
        )
      })}

      {/* Backbone bonds B */}
      {backboneB.slice(0, -1).map((pos, i) => {
        const next = backboneB[i + 1]
        const mid = [(pos[0] + next[0]) / 2, (pos[1] + next[1]) / 2, (pos[2] + next[2]) / 2]
        const dx = next[0] - pos[0]
        const dy = next[1] - pos[1]
        const dz = next[2] - pos[2]
        const len = Math.hypot(dx, dy, dz)
        return (
          <mesh key={`bb${i}`} position={mid} quaternion={bondQuat([dx, dy, dz])}>
            <cylinderGeometry args={[0.04, 0.04, len, 6]} />
            <meshStandardMaterial color={C.mutedBlue} metalness={0.4} roughness={0.5} />
          </mesh>
        )
      })}

      {/* Base pairs — rungs connecting A to B */}
      {basePairs.map((bp, i) => {
        const mid = [
          (bp.posA[0] + bp.posB[0]) / 2,
          (bp.posA[1] + bp.posB[1]) / 2,
          (bp.posA[2] + bp.posB[2]) / 2,
        ]
        const dx = bp.posB[0] - bp.posA[0]
        const dy = bp.posB[1] - bp.posA[1]
        const dz = bp.posB[2] - bp.posA[2]
        const len = Math.hypot(dx, dy, dz)
        // Split rung into two halves with base colours
        const midA = [(bp.posA[0] + mid[0]) / 2, mid[1], (bp.posA[2] + mid[2]) / 2]
        const midB = [(bp.posB[0] + mid[0]) / 2, mid[1], (bp.posB[2] + mid[2]) / 2]
        const colorA = bp.color
        const colorB = BASE_COLORS[(i + 2) % 4] // complementary base
        return (
          <group key={`bp${i}`}>
            {/* Half-rung A */}
            <mesh position={midA} quaternion={bondQuat([dx, dy, dz])}>
              <cylinderGeometry args={[0.055, 0.055, len * 0.48, 6]} />
              <meshStandardMaterial
                color={colorA}
                emissive={colorA}
                emissiveIntensity={0.12}
                metalness={0.2}
                roughness={0.55}
              />
            </mesh>
            {/* Half-rung B */}
            <mesh position={midB} quaternion={bondQuat([dx, dy, dz])}>
              <cylinderGeometry args={[0.055, 0.055, len * 0.48, 6]} />
              <meshStandardMaterial
                color={colorB}
                emissive={colorB}
                emissiveIntensity={0.12}
                metalness={0.2}
                roughness={0.55}
              />
            </mesh>
          </group>
        )
      })}
    </group>
  )
}

// ── Nanopore ───────────────────────────────────────────────────────────────
// Flat horizontal membrane (large disc with hole = ring geometry) at Y=0.
// A tight glowing rim marks the pore opening. Protein nodes dot the surface.
// The membrane fades in as the helix approaches and out after threading.
function Nanopore() {
  const group = useRef()
  const sheet = useRef()
  const rim = useRef()

  // Protein nodes distributed on the membrane surface (not in the pore hole)
  const nodes = useMemo(() => {
    const list = []
    for (let i = 0; i < 60; i += 1) {
      const a = seededRandom(i) * Math.PI * 2
      // Keep nodes outside the pore radius (1.1) and inside membrane edge (~5)
      const r = 1.25 + seededRandom(i + 10) * 3.8
      list.push({
        x: Math.cos(a) * r,
        z: Math.sin(a) * r,
        r: 0.04 + seededRandom(i + 20) * 0.06,
        color: seededRandom(i + 30) > 0.5 ? C.steel : C.slate,
      })
    }
    return list
  }, [])

  useFrame((state, delta) => {
    if (!group.current) return
    const p = progressApi.current
    const visible =
      smooth(BEATS.poreInStart, BEATS.poreInEnd, p) *
      (1 - smooth(BEATS.poreOutStart, BEATS.poreOutEnd, p))

    const pulse = 1 + Math.sin(state.clock.elapsedTime * 1.4) * 0.006
    poreScale.set(pulse, 1, pulse)
    group.current.scale.lerp(poreScale, 1 - Math.exp(-delta * 3.5))
    group.current.visible = visible > 0.01
    if (sheet.current) sheet.current.opacity = visible * 0.78
    if (rim.current) rim.current.opacity = visible * 0.95
  })

  return (
    <group ref={group} position={[0, 0, 0]}>
      {/* Main membrane sheet — ring with hole radius 1.05 */}
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.05, 5.8, 128]} />
        <meshStandardMaterial
          ref={sheet}
          color="#2e4a52"
          emissive="#0e2428"
          emissiveIntensity={0.3}
          metalness={0.5}
          roughness={0.5}
          transparent
          side={THREE.DoubleSide}
          depthWrite={false}
        />
      </mesh>
      {/* Glowing rim around the pore opening */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.01, 0]}>
        <ringGeometry args={[1.0, 1.18, 96]} />
        <meshStandardMaterial
          ref={rim}
          color="#5a9a92"
          emissive="#2a6a62"
          emissiveIntensity={0.9}
          metalness={0.5}
          roughness={0.25}
          transparent
          side={THREE.DoubleSide}
        />
      </mesh>
      {/* Protein nodes on membrane */}
      {nodes.map((n, i) => (
        <mesh key={i} position={[n.x, 0.015, n.z]}>
          <sphereGeometry args={[n.r, 6, 6]} />
          <meshStandardMaterial color={n.color} metalness={0.4} roughness={0.5} />
        </mesh>
      ))}
    </group>
  )
}

// ── Starfield ──────────────────────────────────────────────────────────────
function Starfield() {
  const points = useRef()
  const data = useRef(null)
  if (!data.current) {
    const count = 900
    const positions = new Float32Array(count * 3)
    const colors = new Float32Array(count * 3)
    const seeds = new Float32Array(count)
    for (let i = 0; i < count; i += 1) {
      const o = i * 3
      positions[o] = (seededRandom(i + 1) - 0.5) * 40
      positions[o + 1] = seededRandom(i + 2) * 18 - 6
      positions[o + 2] = (seededRandom(i + 3) - 0.5) * 30 - 4
      seeds[i] = seededRandom(i + 4)
      const shade = 0.55 + seeds[i] * 0.45
      const tone = seededRandom(i + 5)
      if (tone < 0.7) {
        colors[o] = shade * 0.85
        colors[o + 1] = shade * 0.9
        colors[o + 2] = shade
      } else {
        colors[o] = shade * 0.55
        colors[o + 1] = shade * 0.8
        colors[o + 2] = shade * 0.75
      }
    }
    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    data.current = { geometry, seeds, count }
  }

  useFrame((state) => {
    if (!points.current || !data.current) return
    const p = progressApi.current
    const clear = smooth(BEATS.clearStart, BEATS.clearEnd, p)
    const t = state.clock.elapsedTime
    const positions = data.current.geometry.attributes.position.array
    const { seeds, count } = data.current

    for (let i = 0; i < count; i += 1) {
      const o = i * 3
      positions[o] += 0.0004 + seeds[i] * 0.0007
      positions[o + 1] += Math.sin(t * 0.08 + seeds[i] * 12) * 0.00035
      if (positions[o] > 20) positions[o] = -20
    }
    data.current.geometry.attributes.position.needsUpdate = true
    points.current.material.opacity = 0.55 * (1 - clear * 0.65) + 0.12
  })

  return (
    <points ref={points} geometry={data.current.geometry}>
      <pointsMaterial
        vertexColors
        size={0.028}
        sizeAttenuation
        transparent
        opacity={0.55}
        depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </points>
  )
}
